//! Private EPUB library + Gutenberg discovery using the public broker and shared reader.
use crate::{*,serde_json::{json,Value}};
const RECENT:&str="ebooks_recent_v1";
const LIB:&str="ebooks_library_v1";const PREFS:&str="ebooks_preferences_v1";
fn rows(v:&Value)->Vec<Value>{v.as_array().cloned().unwrap_or_default()}
fn library(_s:&mut Value,after:&str)->Value{collections::page(LIB,after,None,"book.library.loaded")}
fn search(s:&mut Value,start:u64)->Value{s["pending_query"]=s["query"].clone();s["pending_start"]=json!(start);effect("ebooks.search",json!({"query":s["query"],"start":start}),"book.found")}
fn change(s:&mut Value,op:&str)->Value{s["mutation"]=json!(op);let id=if op=="add"{s["draft"]["id"].as_str()}else{s["active"]["id"].as_str()}.unwrap_or("").to_owned();s["changing"]=json!(id);collections::get(LIB,&id,"book.change.loaded")}
fn remember_recent(s:&mut Value)->Value{let mut recent=vec![s["active"].clone()];recent.extend(rows(&s["recent"]).into_iter().filter(|b|b["id"]!=s["active"]["id"]).take(29));s["recent"]=json!(recent);collections::transact(RECENT,s["recent_revision"].as_u64().unwrap_or(0),1,None,vec![collections::put("items",json!({"items":s["recent"]}))],"book.recent.saved")}
fn hero(id:&str,t:&str)->Value{let mut n=heading(id,t);n["font"]=json!(22);n}
pub fn controller(input:Value)->Value{
 let mut s=input["state"].clone();if !s.is_object(){s=json!({"view":"discover","tab":"discover","recent":[],"library":[],"next":null,"query":"","filter":"","results":[],"catalog_next":null,"font":18,"active":null,"reader":null,"marks":false,"settings":false,"status":""});}
 if !s["recent"].is_array(){s["recent"]=json!([]);}if !s["tab"].is_string(){s["tab"]=json!("library");}
 let e=&input["event"];let a=e["action"].as_str().unwrap_or("");let ok=e["reply"]["ok"]==true;let v=&e["reply"]["value"];let mut req=Value::Null;let mut event=e.clone();
 match a{
 "start"=>req=collections::get(PREFS,"display","book.preferences"),
 "book.preferences"=>{if ok{s["font"]=json!(v["data"]["font"].as_u64().unwrap_or(18).clamp(14,28));}req=collections::get(RECENT,"items","book.recents.loaded")},
 "book.recents.loaded"=>{if ok{s["recent_revision"]=v["revision"].clone();s["recent"]=json!(rows(&v["data"]["items"]).into_iter().take(30).collect::<Vec<_>>());}req=library(&mut s,"")},
 "book.library"|"book.library.refresh"=>{s["view"]=json!("library");s["tab"]=json!("library");s["library_page"]=json!(false);s["status"]=json!("");s["active"]=Value::Null;s["reader"]=Value::Null;req=library(&mut s,"")},
 "book.more"=>{s["library_page"]=json!(true);let n=s["next"].as_str().unwrap_or("").to_owned();req=library(&mut s,&n)},
 "book.library.loaded" if ok=>{s["library"]=json!(rows(&v["items"]).iter().map(|r|r["data"].clone()).collect::<Vec<_>>());s["next"]=v["next"].clone()},
 "book.filter"=>s["filter"]=e["value"].clone(),"book.query"=>s["query"]=e["value"].clone(),
 "book.discover"|"book.browse.empty"=>{s["view"]=json!("discover");s["tab"]=json!("discover");s["active"]=Value::Null;s["status"]=json!("");if !rows(&s["results"]).is_empty(){req=search(&mut s,1)}},
 "book.recent"=>{s["view"]=json!("recent");s["tab"]=json!("recent");s["active"]=Value::Null;s["status"]=json!("")},
 "book.back"=>{s["view"]=s["tab"].clone();s["active"]=Value::Null;s["reader"]=Value::Null;s["status"]=json!("");if s["view"]=="library"{req=library(&mut s,"")}else if s["view"]=="discover"&&!rows(&s["results"]).is_empty(){req=search(&mut s,1)}},
 "book.topic"=>{s["query"]=e["value"].clone();req=search(&mut s,1)},
 _ if a.starts_with("book.preview.")=>{if let Ok(id)=a[13..].parse::<u64>(){if let Some(b)=rows(&s["results"]).into_iter().find(|r|r["id"]==id&&r["in_library"]!=true){s["preview"]=b;req=effect("ebooks.search",json!({"query":format!("id:{id}"),"start":1}),"book.description");s["view"]=json!("preview");s["status"]=json!("");}}},
 "book.description" if ok=>{if let Some(row)=rows(&v["items"]).into_iter().find(|r|r["id"]==s["preview"]["id"]){s["preview"]["description"]=json!(row["description"].as_str().filter(|s|!s.trim().is_empty()).unwrap_or("Description unavailable."));s["preview"]["in_library"]=row["in_library"].clone();}},
 "book.description"=>{s["preview"]["description"]=json!("Description unavailable.");},
 "book.search"=>req=search(&mut s,1),"book.search.more"=>{if let Some(n)=s["catalog_next"].as_u64(){req=search(&mut s,n)}},
 "book.found" if ok=>{s["results"]=v["items"].clone();s["catalog_next"]=v["next"].clone();s["searched_query"]=s["pending_query"].clone();s["status"]=json!(if rows(&v["items"]).is_empty(){"No matching books. Try another title or author."}else{""})},
 "book.import"|"book.settings.import"=>{s["settings"]=json!(false);s["source"]=json!("Imported");s["gutenberg_id"]=Value::Null;req=blobs::import(false,"book.file")},
 _ if a.starts_with("book.acquire.")=>{if let Ok(id)=a[13..].parse::<u64>(){if rows(&s["results"]).iter().any(|r|r["id"]==id&&r["in_library"]!=true){s["source"]=json!("Project Gutenberg");req=effect("ebooks.acquire",json!({"id":id}),"book.file")}}},
 "book.file" if ok=>{s["file"]=v["id"].clone();s["gutenberg_id"]=v["gutenberg_id"].clone();req=epub::info(v["id"].as_str().unwrap_or(""),"book.info")},
 "book.info" if ok=>{s["draft"]=json!({"id":s["file"],"title":v["title"],"author":v["author"],"source":s["source"],"gutenberg_id":s["gutenberg_id"],"marks":[]});req=change(&mut s,"add")},
 "book.info"=>{s["status"]=json!("This is not a supported reflowable, DRM-free EPUB. Your library was kept.");if let Some(id)=s["file"].as_str(){req=blobs::delete(id,"book.invalid.cleaned")}},
 _ if a.starts_with("book.open.")=>{if let Some(b)=rows(&s["library"]).into_iter().chain(rows(&s["recent"])).find(|b|b["id"]==&a[10..]){s["active"]=b;s["reader"]=Value::Null;s["view"]=json!("opening");s["marks"]=json!(false);req=remember_recent(&mut s)}},
 "book.read"=>{if s["active"].is_object(){s["view"]=json!("opening");s["reader"]=Value::Null;req=remember_recent(&mut s)}},
 "book.recent.saved"=>{if ok{s["recent_revision"]=v["revision"].clone();}s["view"]=json!("read");event=Value::Null},
 "book.bookmark"=>{let r=&s["reader"];s["new_mark"]=json!({"chapter":r["chapter"]["chapter"],"offset":r["reading"]["offset"],"label":format!("{} · page {}",r["chapter"]["title"].as_str().unwrap_or("Chapter"),r["reading"]["offset"].as_u64().unwrap_or(0)/4000+1)});req=change(&mut s,"bookmark")},
 "book.marks"=>{s["marks"]=json!(true);s["mark_page"]=json!(0)},"book.marks.close"=>s["marks"]=json!(false),
 "book.marks.next"=>s["mark_page"]=json!(s["mark_page"].as_u64().unwrap_or(0)+20),"book.marks.previous"=>s["mark_page"]=json!(s["mark_page"].as_u64().unwrap_or(0).saturating_sub(20)),
 _ if a.starts_with("book.mark.goto.")=>{if let Some(m)=a[15..].parse::<usize>().ok().and_then(|i|s["active"]["marks"].as_array().and_then(|m|m.get(i))).cloned(){s["marks"]=json!(false);event=json!({"action":"epub.goto","value":m})}},
 _ if a.starts_with("book.mark.delete.")=>{if let Ok(i)=a[17..].parse::<usize>(){s["delete_mark"]=json!(i);req=change(&mut s,"unbookmark")}},
 "book.remove"=>{s["settings"]=json!(false);s["remove"]=json!(true)},"book.keep"=>s["remove"]=json!(false),"book.remove.accept"=>{s["remove"]=json!(false);req=change(&mut s,"remove")},
 "book.change.loaded" if ok=>{let op=s["mutation"].as_str().unwrap_or("").to_owned();let mut data=if op=="add"{s["draft"].clone()}else{v["data"].clone()};if !data.is_object(){s["status"]=json!("Book changed in another session. Reload your library.")}else{let mut marks=rows(&data["marks"]);if op=="bookmark"&&!marks.iter().any(|m|m["chapter"]==s["new_mark"]["chapter"]&&m["offset"]==s["new_mark"]["offset"]){if marks.len()<80{marks.push(s["new_mark"].clone())}else{s["status"]=json!("Remove an older bookmark before adding another.")}}if op=="unbookmark"{if let Some(i)=s["delete_mark"].as_u64().map(|i|i as usize).filter(|i|*i<marks.len()){marks.remove(i);}}data["marks"]=json!(marks);s["changed"]=data.clone();req=collections::transact(LIB,v["revision"].as_u64().unwrap_or(0),1,None,vec![if op=="remove"{collections::delete(s["changing"].as_str().unwrap_or(""))}else{collections::put(s["changing"].as_str().unwrap_or(""),data)}],"book.changed")}},
 "book.changed" if ok=>{match s["mutation"].as_str().unwrap_or(""){"remove"=>req=blobs::delete(s["changing"].as_str().unwrap_or(""),"book.removed"),"add"=>{s["active"]=s["changed"].clone();s["reader"]=Value::Null;s["view"]=json!("ready");let id=s["active"]["gutenberg_id"].clone();for row in s["results"].as_array_mut().into_iter().flatten(){if !id.is_null()&&row["id"]==id{row["in_library"]=json!(true);}}event=Value::Null},_=>{s["active"]=s["changed"].clone();s["status"]=json!("Bookmarks saved")}}},
 "book.removed"=>{s["active"]=Value::Null;s["reader"]=Value::Null;s["view"]=json!("library");s["tab"]=json!("library");req=collections::get(RECENT,"items","book.recent.remove.before")},
 "book.recent.remove.before" if ok=>{s["recent"]=json!(rows(&v["data"]["items"]).into_iter().filter(|b|b["id"]!=s["changing"]).collect::<Vec<_>>());req=collections::transact(RECENT,v["revision"].as_u64().unwrap_or(0),1,None,vec![collections::put("items",json!({"items":s["recent"]}))],"book.recent.removed")},
 "book.recent.removed"=>{if ok{s["recent_revision"]=v["revision"].clone();}req=library(&mut s,"")},
 "book.search.text"=>{s["settings"]=json!(false);event=json!({"action":"epub.search"})},
 "book.settings"=>s["settings"]=json!(true),"book.settings.close"=>s["settings"]=json!(false),
 "book.font.small"|"book.font.large"=>{let n=s["font"].as_i64().unwrap_or(18)+if a=="book.font.large"{2}else{-2};s["font"]=json!(n.clamp(14,28));req=collections::get(PREFS,"display","book.font.loaded")},
 "book.font.loaded" if ok=>req=collections::transact(PREFS,v["revision"].as_u64().unwrap_or(0),1,None,vec![collections::put("display",json!({"font":s["font"]}))],"book.font.saved"),
 "book.speech.next"=>{let r=&s["reader"];let text=r["chapter"]["text"].as_str().unwrap_or("");let at=r["reading"]["offset"].as_u64().unwrap_or(0)as usize;event=json!({"action":if reading::page(text,at,4000).is_ok_and(|p|p.end<text.len()){"reading.next"}else{"epub.next"}})},_=>{}
 }
 if e["reply"]["ok"]==false&&a!="book.info"{s["status"]=json!(e["reply"]["error"].as_str().unwrap_or("Action failed. Your saved books are kept."));}
 if s["view"]=="read"&&s["active"].is_object(){
  let id=s["active"]["id"].as_str().unwrap_or("").to_owned();let mut f=epub_ui::reader("eBooks",json!({"state":s["reader"],"event":event}),&id);s["reader"]=f["state"].clone();
  if f["close_requested"]==true{s["active"]=Value::Null;s["reader"]=Value::Null;s["view"]=s["tab"].clone();if s["view"]=="library"{req=library(&mut s,"");}}else{
   if req.is_null(){req=f["effect"].clone();}
   if s["reader"]["mode"]=="read"&&s["reader"]["phase"]=="read"{
    let mut body=rows(&f["body"]);body.retain(|n|!matches!(n["id"].as_str(),Some("reading.query"|"reading.find"|"reading.progress")));for n in &mut body{match n["id"].as_str().unwrap_or(""){"reading.page"=>{n["font"]=s["font"].clone();n["selectable"]=json!(true)},"epub.title"=>n["font"]=json!(22),"epub.chapter_title"=>n["font"]=json!(17),"reading.previous"|"reading.next"=>n["row"]=json!("ebook.pages"),"epub.next"|"epub.previous"=>n["row"]=json!("ebook.chapters"),_=>{}}}
    let r=&s["reader"];let text=r["chapter"]["text"].as_str().unwrap_or("");let at=r["reading"]["offset"].as_u64().unwrap_or(0)as usize;let page=reading::page(text,at,4000).ok();let end=page.as_ref().map_or(0,|p|p.end);let chapter=r["chapter"]["chapter"].as_u64().unwrap_or(0);let count=r["book"]["chapters"].as_array().map_or(1,Vec::len);let spoken=if r["reading"]["ready"]==true{page.map(|p|p.text.to_owned()).unwrap_or_default()}else{String::new()};let mut speech=json!({"kind":"speech","id":"ebook.read.aloud","book":id,"value":spoken,"compact":true});if end<text.len()||chapter+1<count as u64{speech["on_done"]=json!("book.speech.next")};body.insert(2,speech);body.push(label("book.progress",&format!("Chapter {} of {} · {}% of chapter",chapter+1,count,if text.is_empty(){100}else{at*100/text.len()})));body.push(button("book.bookmark","Bookmark page").row("ebook.tools"));body.push(button("book.marks","Bookmarks").row("ebook.tools"));body.push(label("book.status",s["status"].as_str().unwrap_or("")));f["body"]=json!(body);f["actions"]=json!([icon("book.settings","Reader settings","settings"),icon("epub.toc","Contents","menu")]);
   }
   if s["reader"]["mode"]=="read"&&!rows(&f["body"]).iter().any(|n|n["id"]=="ebook.read.aloud"){f["body"].as_array_mut().unwrap().push(json!({"kind":"speech","id":"ebook.read.aloud","book":id,"value":"","compact":true}));}
   if s["marks"]==true{let mut body=vec![hero("book.marks.title","Your bookmarks")];for(i,m)in rows(&s["active"]["marks"]).iter().enumerate().skip(s["mark_page"].as_u64().unwrap_or(0)as usize).take(20){body.push(button(&format!("book.mark.goto.{i}"),m["label"].as_str().unwrap_or("Bookmark")).row(&format!("mark.{i}")));body.push(button(&format!("book.mark.delete.{i}"),"Delete").row(&format!("mark.{i}")));}if body.len()==1{body.push(label("book.marks.empty","Bookmark a page to return to it later."));}if s["mark_page"].as_u64().unwrap_or(0)>0{body.push(button("book.marks.previous","Previous bookmarks"));}if s["mark_page"].as_u64().unwrap_or(0)+20<rows(&s["active"]["marks"]).len()as u64{body.push(button("book.marks.next","More bookmarks"));}body.push(button("book.marks.close","Back to book"));f["body"]=json!(body);f["back_action"]=json!("book.marks.close");}
   if s["settings"]==true{f["menu_open"]=json!(true);f["menu_title"]=json!("Reading & Read Aloud");f["menu_close"]=json!("book.settings.close");f["menu"]=json!([label("book.font.label",&format!("Text size · {}",s["font"])),button("book.font.small","Smaller text").row("ebook.font"),button("book.font.large","Larger text").row("ebook.font"),json!({"kind":"speech_settings","id":"ebook.voice.settings"}),button("book.search.text","Search this book"),button("book.remove","Remove book"),button("book.settings.close","Done")]);}
   if s["remove"]==true{f["confirm"]=json!({"title":"Remove book?","text":"Remove this private ebook copy. Your original file stays untouched.","accept":"book.remove.accept","cancel":"book.keep","accept_label":"Remove"});}
   f["scroll_body"]=json!(true);f["state"]=s;f["effect"]=req;return f
  }
 }
 let mut body=Vec::new();
 for(id,text,value)in[("book.discover","Browse","discover"),("book.recent","Recent","recent"),("book.library","My Library","library")]{let mut n=button(id,text).row("ebook.tabs");n["tab"]=json!(true);n["selected"]=json!(s["tab"]==value);body.push(n);}
 if s["view"]=="ready"{body.push(button("book.back","‹ Back"));body.push(hero("book.ready.title",s["active"]["title"].as_str().unwrap_or("Your book")));body.push(label("book.ready.author",s["active"]["author"].as_str().unwrap_or("")));body.push(label("book.ready.offline","Downloaded"));body.push(primary_button("book.read","Read now"));}
 else if s["view"]=="preview"{body.push(button("book.back","‹ Back"));body.push(hero("book.preview.title",s["preview"]["title"].as_str().unwrap_or("Book")));body.push(label("book.preview.author",s["preview"]["author"].as_str().unwrap_or("")));body.push(label("book.preview.description",s["preview"]["description"].as_str().unwrap_or("Loading description…")));if let Some(id)=s["preview"]["id"].as_u64(){body.push(primary_button(&format!("book.acquire.{id}"),if s["preview"]["in_library"]==true{"Already in your library"}else{"Download book"}).enabled(s["preview"]["in_library"]!=true));}}
 else if s["view"]=="opening"{body.push(label("book.opening","Opening book…"));body.push(button("book.back","Back"));}
 else if s["view"]=="discover"{
  body.push(hero("book.discover.title","Project Gutenberg"));
  body.push(field("book.query","Search title, author or subject",s["query"].as_str().unwrap_or("")).limit(100));
  body.push(choices("chips","book.topic","Topics",s["query"].as_str().unwrap_or(""),&[("","All"),("fiction","Fiction"),("mystery","Mystery"),("history","History"),("children","Children"),("poetry","Poetry")]));
  body.push(primary_button("book.search",if s["query"].as_str().unwrap_or("").is_empty(){"Browse books"}else{"Find books"}));
  for b in rows(&s["results"]){if let Some(id)=b["id"].as_u64(){body.push(record(&format!("book.preview.{id}"),b["title"].as_str().unwrap_or("Book"),&if b["in_library"]==true{format!("{} · Already in your library",b["author"].as_str().unwrap_or(""))}else{b["author"].as_str().unwrap_or("").to_string()}).enabled(b["in_library"]!=true));}}
  if s["catalog_next"].is_number(){body.push(button("book.search.more","More books").enabled(s["query"]==s["searched_query"]));}}
 else if s["view"]=="recent"{let recent=rows(&s["recent"]);if recent.is_empty(){body.push(label("book.recent.empty","No recent books"));body.push(button("book.browse.empty","Browse books"));}for b in recent{body.push(record(&format!("book.open.{}",b["id"].as_str().unwrap_or("")),b["title"].as_str().unwrap_or("Book"),b["author"].as_str().unwrap_or("")));}}
 else{
  body.push(primary_button("book.import","Add EPUB"));body.push(field("book.filter","Search this library page",s["filter"].as_str().unwrap_or("")).limit(100));
  let filter=s["filter"].as_str().unwrap_or("").to_lowercase();let mut books=rows(&s["library"]);books.sort_by_key(|b|b["title"].as_str().unwrap_or("").to_lowercase());if books.is_empty(){body.push(label("book.empty","No books in your library"));body.push(button("book.browse.empty","Browse books"));}
  for b in books{if format!("{} {}",b["title"],b["author"]).to_lowercase().contains(&filter){body.push(record(&format!("book.open.{}",b["id"].as_str().unwrap_or("")),b["title"].as_str().unwrap_or("Book"),b["author"].as_str().unwrap_or("")));}}
  if s["next"].is_string(){body.push(button("book.more","More saved books"));}if s["library_page"]==true{body.push(button("book.library.refresh","First library page"));}}
 if s["status"].as_str().is_some_and(|s|!s.is_empty()){body.push(label("book.status",s["status"].as_str().unwrap()));}
 let settings=s["settings"]==true;let details=matches!(s["view"].as_str(),Some("preview"|"ready"|"opening"));
 let mut screen=Screen::new("eBooks",s).body(body).actions(vec![icon("book.settings","eBooks settings","settings")]).scrollable().effect(req);
 if details{screen=screen.back("book.back");}
 if settings{screen=screen.dialog("eBooks settings","book.settings.close",vec![label("book.source","Source: Project Gutenberg"),button("book.settings.import","Add EPUB"),json!({"kind":"speech_settings","id":"ebook.home.voice"}),button("book.settings.close","Done")]);}screen.finish()

}
#[cfg(test)]mod tests{use super::*;#[test]fn starts_offline_and_only_acquires_displayed_catalog_ids(){let f=controller(json!({"event":{"action":"start"}}));assert_eq!(f["effect"]["service"],"collections.get");let mut s=f["state"].clone();s["results"]=json!([{"id":11,"title":"Alice","author":"Carroll"}]);let d=controller(json!({"state":s,"event":{"action":"book.acquire.11"}}));assert_eq!(d["effect"]["service"],"ebooks.acquire");let bad=controller(json!({"state":d["state"],"event":{"action":"book.acquire.999"}}));assert!(bad["effect"].is_null());}}

#[cfg(test)]mod reading_tests{use super::*;
fn state()->Value{let id="a".repeat(32);json!({"view":"read","font":20,"active":{"id":id,"title":"Book","marks":[]},"reader":{"format":"onklav.epub.ui.v1","id":id,"book":{"revision":"r","chapters":[{"chapter":0}],"toc":[]},"chapter":{"chapter":0,"title":"One","text":"x".repeat(5000),"anchors":{}},"reading":{"format":"onklav.reading.ui.v1","content":format!("epub_{id}_0"),"revision":"r","offset":0,"ready":true,"busy":false,"dirty":false,"store_revision":0},"mode":"read","phase":"read"}})}
#[test]fn read_aloud_uses_current_page_and_auto_advances_without_network(){let f=controller(json!({"state":state(),"event":{"action":"noop"}}));let speech=f["body"].as_array().unwrap().iter().find(|n|n["id"]=="ebook.read.aloud").unwrap();assert_eq!(speech["value"].as_str().unwrap().chars().count(),4000);assert_eq!(speech["on_done"],"book.speech.next");let next=controller(json!({"state":f["state"],"event":{"action":"book.speech.next"}}));assert_eq!(next["state"]["reader"]["reading"]["offset"],4000);assert_eq!(next["effect"]["service"],"collections.transact");let speech=next["body"].as_array().unwrap().iter().find(|n|n["id"]=="ebook.read.aloud").unwrap();assert!(speech.get("on_done").is_none());}
#[test]fn bookmarks_are_paged_and_mutations_require_latest_revision(){let mut s=state();s["active"]["marks"]=json!((0..80).map(|i|json!({"chapter":0,"offset":i,"label":format!("Page {i}")})).collect::<Vec<_>>());let f=controller(json!({"state":s,"event":{"action":"book.marks"}}));assert!(f["body"].as_array().unwrap().len()<50);let f=controller(json!({"state":f["state"],"event":{"action":"book.bookmark"}}));assert_eq!(f["effect"]["service"],"collections.get");}
}

#[cfg(test)]mod saved_screen_tests{use super::*;#[test]fn finishing_import_yields_before_opening_reader(){let f=controller(json!({"state":{"view":"library","mutation":"add","changed":{"id":"a".repeat(32),"title":"Book"}},"event":{"action":"book.changed","reply":{"ok":true,"value":{"revision":1}}}}));assert_eq!(f["state"]["view"],"ready");assert!(f["effect"].is_null());assert!(f["body"].as_array().unwrap().iter().any(|n|n["id"]=="book.read"));}}

#[cfg(test)]mod polish_tests{
 use super::*;
 #[test]fn browse_recent_library_tabs_and_previews_are_clear(){let f=controller(json!({}));let tabs:Vec<_>=f["body"].as_array().unwrap().iter().filter(|n|n["tab"]==true).map(|n|n["text"].as_str().unwrap()).collect();assert_eq!(tabs,vec!["Browse","Recent","My Library"]);assert_eq!(f["state"]["view"],"discover");assert!(!f["body"].to_string().contains("No account"));let mut s=f["state"].clone();s["results"]=json!([{"id":11,"title":"Alice","author":"Carroll"}]);let f=controller(json!({"state":s,"event":{"action":"book.preview.11"}}));assert_eq!(f["effect"]["args"]["query"],"id:11");assert_eq!(f["back_action"],"book.back");assert!(f["body"].as_array().unwrap().iter().any(|n|n["id"]=="book.acquire.11"));}
 #[test]fn recent_load_and_open_preserve_source_and_use_persistent_collection(){let f=controller(json!({"event":{"action":"book.recents.loaded","reply":{"ok":true,"value":{"data":{"items":[{"id":"a".repeat(32),"title":"Book","marks":[]}]}}}}}));let f=controller(json!({"state":f["state"],"event":{"action":"book.recent"}}));let id=format!("book.open.{}","a".repeat(32));assert!(f["body"].as_array().unwrap().iter().any(|n|n["id"]==id));let f=controller(json!({"state":f["state"],"event":{"action":id}}));assert_eq!(f["effect"]["service"],"collections.transact");assert_eq!(f["effect"]["args"]["name"],RECENT);assert_eq!(f["state"]["tab"],"recent");}
}
#[cfg(test)]mod duplicate_tests{use super::*;
 #[test]fn owned_search_rows_are_disabled_and_cannot_open_or_download(){let mut s=controller(json!({}))["state"].clone();s["results"]=json!([{"id":11,"title":"Alice","author":"Carroll","in_library":true}]);let f=controller(json!({"state":s}));let row=f["body"].as_array().unwrap().iter().find(|n|n["id"]=="book.preview.11").unwrap();assert_eq!(row["enabled"],false);assert!(row["detail"].as_str().unwrap().contains("Already in your library"));for action in ["book.preview.11","book.acquire.11"]{let f=controller(json!({"state":f["state"],"event":{"action":action}}));assert!(f["effect"].is_null());assert_eq!(f["state"]["view"],"discover");}}
 #[test]fn downloaded_identity_is_kept_and_results_update_without_relaunch(){let mut s=controller(json!({}))["state"].clone();s["mutation"]=json!("add");s["changed"]=json!({"id":"a".repeat(32),"gutenberg_id":11,"title":"Alice"});s["results"]=json!([{"id":11,"title":"Alice"}]);let f=controller(json!({"state":s,"event":{"action":"book.changed","reply":{"ok":true,"value":{"revision":1}}}}));assert_eq!(f["state"]["active"]["gutenberg_id"],11);assert_eq!(f["state"]["results"][0]["in_library"],true);}
}
